mcp:tool-listener.mcp:parameters-schema:
{
				"$schema": "http://json-schema.org/draft-07/schema#", 
				"type": "object", 
				"properties": {
					"userName": {"type": "string","description": "Name of the user to look up"}
				}, 
				"required": ["userName"]
			}

ee:message.ee:set-payload:
%dw 2.0
        output application/json
        ---
        [{
"name":"anirban",
"age" : "35",
"address" : "123 road, Hyd"
},
{
"name":"Sujay",
"age" : "36",
"address" : "456 road, Hyd"
},
{
"name":"Ankur",
"age" : "34",
"address" : "789 road, Hyd"
}
]

%dw 2.0
output application/json
---
{

	"status": "success",
	"processedAt": now(),

	"result": (payload filter ($.name == vars.toolUserName))[0] default {
		"error": "User not found via MCP tool"
	}
}

%dw 2.0
output application/json
---
payload filter (
    if (vars.categoryFilter != null and vars.categoryFilter != "")
        do {
            var requestCats = (vars.categoryFilter splitBy ",") map trim($)
            var ruleCats = ($.category splitBy ",") map trim($)
            ---
            sizeOf(requestCats -- (requestCats -- ruleCats)) > 0
        }
    else
        true
)

%dw 2.0
output application/json
---
if (sizeOf(payload) > 0) {
	"status": "success",
	"processedAt": now(),
	"result": payload
} else {
	"status": "error", 
	"processedAt": now(),
	"error": "rule not found via MCP tool"
}

mcp:tool-listener.mcp:parameters-schema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "description": "Filter rules by category"
    },
    "type": {
      "type": "string",
      "description": "Filter by document type (hld, lld, sdd)"
    }
  },
  "additionalProperties": false
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "description": "Filter rules by category"
    },
    "type": {
      "type": "string",
      "description": "Filter by document type (hld, lld, sdd)"
    }
  },
  "additionalProperties": false
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
payload filter (
    (
        if (vars.docCategoryFilter != null and vars.docCategoryFilter != "")
            do {
                var reqCats  = (vars.docCategoryFilter splitBy ",") map trim($)
                var ruleCats = ($.category splitBy ",") map trim($)
                ---
                sizeOf(reqCats -- (reqCats -- ruleCats)) > 0
            }
        else true
    )
    and
    (
        if (vars.docTypeFilter != null and vars.docTypeFilter != "")
            do {
                var reqTypes  = (vars.docTypeFilter splitBy ",") map trim($)
                var ruleTypes = ($."type" splitBy ",") map trim($)
                ---
                sizeOf(reqTypes -- (reqTypes -- ruleTypes)) > 0
            }
        else true
    )
)

%dw 2.0
output application/json
---
if (sizeOf(payload) > 0) {
    "status":      "success",
    "processedAt": now(),
    "result":      payload
} else {
    "status":      "error",
    "processedAt": now(),
    "error":       "No document rules found via MCP tool"
}

mcp:tool-listener.mcp:parameters-schema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "complexity": {
      "type": "string",
      "description": "Filter by complexity level (Very Simple, Simple, Medium, Complex, Very Complex)",
      "enum": ["Very Simple", "Simple", "Medium", "Complex", "Very Complex"]
    },
    "category": {
      "type": "string",
      "description": "Filter by API category (e.g., 'Consumer Facing API', 'Process API')"
    },
    "minEffortDays": {
      "type": "number",
      "description": "Minimum end-to-end effort days"
    },
    "maxEffortDays": {
      "type": "number",
      "description": "Maximum end-to-end effort days"
    }
  },
  "additionalProperties": false
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "complexity": {
      "type": "string",
      "description": "Filter by complexity level (Very Simple, Simple, Medium, Complex, Very Complex)",
      "enum": ["Very Simple", "Simple", "Medium", "Complex", "Very Complex"]
    },
    "category": {
      "type": "string",
      "description": "Filter by API category (e.g., 'Consumer Facing API', 'Process API')"
    },
    "minEffortDays": {
      "type": "number",
      "description": "Minimum end-to-end effort days"
    },
    "maxEffortDays": {
      "type": "number",
      "description": "Maximum end-to-end effort days"
    }
  },
  "additionalProperties": false
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
do {
    var allStandards = payload.standards
    var filtered = allStandards filter (
        (vars.estComplexityFilter == null or $.complexity == vars.estComplexityFilter) and
        (vars.estCategoryFilter == null or (($.category default "") contains vars.estCategoryFilter)) and
        (vars.estMinEffort == null or $.endToEndEffortDays >= vars.estMinEffort) and
        (vars.estMaxEffort == null or $.endToEndEffortDays <= vars.estMaxEffort)
    )
    ---
    {
        status: if (sizeOf(filtered) > 0) "success" else "no_results",
        processedAt: now(),
        totalStandards: sizeOf(filtered),
        filters: {
            complexity: vars.estComplexityFilter,
            category: vars.estCategoryFilter,
            minEffortDays: vars.estMinEffort,
            maxEffortDays: vars.estMaxEffort
        },
        standards: filtered
    }
}
